Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='tapgatedmarkednotrefused', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title="Where the owner's tap gates an effect, a round that read outside text files a marked card, never a refusal", body="When the owner's tap is what performs an effect, a round that read outside text still files its card, and the card is marked as written after outside text. The round is not refused. A refusal stays only where a tap alone does not contain the effect.", rationale='The tap shows the owner the exact effect and asks for their word, so a marked card is safe, and a refusal would hide work that the owner could judge. Where no tap stands between the model and the effect, only a refusal contains it.', supersedes=()))